/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  // First line: invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Render line items
  const lineTexts = invoice.lines.map((line) => {
    const total = lineTotal(line);
    const formattedUnitPrice = formatEuros(line.unitPrice);
    const formattedTotal = formatEuros(total);
    let lineText = `${line.qty}x ${line.name} @ ${formattedUnitPrice} = ${formattedTotal}`;

    const discountPercent = line.discountPercent ?? 0;
    if (discountPercent > 0) {
      const discount = lineDiscount(line);
      const formattedDiscount = formatEuros(discount);
      lineText += ` (${discountPercent}% off: -${formattedDiscount})`;
    }

    return lineText;
  });

  // Calculate totals
  const totals = invoiceTotals(invoice);
  const formattedSubtotal = formatEuros(totals.subtotal);
  const formattedDiscount = formatEuros(totals.discount);
  const formattedTotal = formatEuros(totals.total);

  // Assemble all lines
  const allLines = [invoiceNumber, customerName, ...lineTexts];

  if (totals.discount > 0) {
    allLines.push(`Subtotal: ${formattedSubtotal}`);
    allLines.push(`Discount: -${formattedDiscount}`);
  }

  allLines.push(`Total: ${formattedTotal}`);

  return allLines.join('\n');
}

