import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-10-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 8,
    unitPrice: 8500,
    vatRate: 21,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 2,
    unitPrice: 980,
    vatRate: 21,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice returns DATE_INVALID for missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '15-10-2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for non-existent date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for fractional quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice stops at first error in line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice works with single line', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-005');
  assert.equal(result.value.issueDate, '2023-12-25');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 3 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 980 }), 9800);
});

test('lineTotal handles small unit prices', () => {
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 37 }), 74);
});

test('lineTotal handles large quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 120000 }), 120000000);
});

test('invoiceTotals sums a single line', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000);
  assert.equal(totals.total, 68000);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500 },
      { qty: 2, unitPrice: 980 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000 + 1960 + 120000);
  assert.equal(totals.total, 189960);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };

  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);

  assert.notStrictEqual(totals1, totals2);
});

test('invoiceTotals with enriched invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 8 * 8500 + 2 * 980);
  assert.equal(totals.total, 69960);
});

test('addLine adds a new SKU to the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'ICON-SET', qty: 5 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.deepEqual(addResult.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 5,
    unitPrice: 980,
    vatRate: 21,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 11);
});

test('addLine returns QTY_INVALID for bad qty', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: 0 }).error, 'QTY_INVALID');
  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: -5 }).error, 'QTY_INVALID');
  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: 2.5 }).error, 'QTY_INVALID');
});

test('addLine returns UNKNOWN_SKU for invalid SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'INVALID-SKU', qty: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('addLine returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('addLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  const invoice = result.value;
  const originalLinesCopy = JSON.parse(JSON.stringify(invoice.lines));

  addLine(invoice, { sku: 'ICON-SET', qty: 5 });

  assert.deepEqual(invoice.lines, originalLinesCopy);
});

test('addLine preserves other invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  const invoice = result.value;
  const addResult = addLine(invoice, { sku: 'ICON-SET', qty: 5 });

  assert.equal(addResult.value.customerId, 'C-005');
  assert.equal(addResult.value.issueDate, '2023-12-25');
  assert.equal(addResult.value.status, 'draft');
});

test('removeLine removes a line from the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'ICON-SET');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = removeLine(invoice, 'ICON-SET');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'LINE_NOT_FOUND');
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('removeLine returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'ICON-SET', qty: 2, name: 'Icon set (24 icons)', unitPrice: 980, vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'ICON-SET');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  const invoice = result.value;
  const originalLinesCopy = JSON.parse(JSON.stringify(invoice.lines));

  removeLine(invoice, 'ICON-SET');

  assert.deepEqual(invoice.lines, originalLinesCopy);
});

test('removeLine preserves other invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'ICON-SET');

  assert.equal(removeResult.value.customerId, 'C-005');
  assert.equal(removeResult.value.issueDate, '2023-12-25');
  assert.equal(removeResult.value.status, 'draft');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0001');
  assert.equal(issueResult.value.status, 'issued');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2024-10-15');
});

test('issueInvoice uses existing numbers to generate next number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0003'];
  const issueResult = issueInvoice(invoice, existingNumbers);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0004');
});

test('issueInvoice returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'issued',
    number: 'INV-2024-0001',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice preserves all line data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.lines.length, 2);
  assert.deepEqual(issueResult.value.lines[0], invoice.lines[0]);
  assert.deepEqual(issueResult.value.lines[1], invoice.lines[1]);
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  issueInvoice(invoice, []);

  assert.deepEqual(invoice, invoiceCopy);
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2 },
    ],
