    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice stops at first error in line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice works with single line', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-005');
  assert.equal(result.value.issueDate, '2023-12-25');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 3 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 980 }), 9800);
});

test('lineTotal handles small unit prices', () => {
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 37 }), 74);
});

test('lineTotal handles large quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 120000 }), 120000000);
});

test('invoiceTotals sums a single line', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000);
  assert.equal(totals.total, 68000);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500 },
      { qty: 2, unitPrice: 980 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000 + 1960 + 120000);
  assert.equal(totals.total, 189960);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };

  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);

  assert.notStrictEqual(totals1, totals2);
});

test('invoiceTotals with enriched invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 8 * 8500 + 2 * 980);
  assert.equal(totals.total, 69960);
});

test('addLine adds a new SKU to the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
