test('issueInvoice preserves all line data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

