test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  issueInvoice(invoice, []);

  assert.deepEqual(invoice, invoiceCopy);
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

