test('lineDiscount calculates discount amount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 8, unitPrice: 8500, discountPercent: 10 }), 6800);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 50, discountPercent: 25 }), 1250);
});

test('lineDiscount defaults to 0 if discountPercent is missing', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount handles decimal discount percentages', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 12.5 }), 1250);
  assert.equal(lineDiscount({ qty: 8, unitPrice: 8500, discountPercent: 7.5 }), 5100);
});

test('lineDiscount clamps to 0 minimum', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 0 });
  assert.equal(result, 0);
  assert.ok(result >= 0);
});

